+    button.textContent = "Added";
+    button.setAttribute("aria-label", `Added to cart: ${productName}`);
+    window.setTimeout(() => {
+      button.textContent = "Add";
+      button.setAttribute("aria-label", `Add to cart: ${productName}`);
+    }, 1800);
+  });
+});
+
