   <script>
 const navToggle = document.querySelector(".nav-toggle");
 const primaryNav = document.querySelector("#primary-navigation");
 const newsletterForm = document.querySelector(".newsletter-form");
 const emailInput = document.querySelector("#email");
 const formStatus = document.querySelector(".form-status");
 const addButtons = document.querySelectorAll(".icon-button");

 if (navToggle && primaryNav) {
   navToggle.addEventListener("click", () => {
     const isOpen = navToggle.getAttribute("aria-expanded") === "true";

     navToggle.setAttribute("aria-expanded", String(!isOpen));
     primaryNav.classList.toggle("is-open", !isOpen);
     document.body.classList.toggle("nav-open", !isOpen);
   });

   primaryNav.addEventListener("click", (event) => {
     if (event.target instanceof HTMLAnchorElement) {
       navToggle.setAttribute("aria-expanded", "false");
       primaryNav.classList.remove("is-open");
       document.body.classList.remove("nav-open");
     }
   });

   document.addEventListener("keydown", (event) => {
     if (event.key === "Escape" && primaryNav.classList.contains("is-open")) {
       navToggle.setAttribute("aria-expanded", "false");
       primaryNav.classList.remove("is-open");
       document.body.classList.remove("nav-open");
       navToggle.focus();
     }
   });
 }

 addButtons.forEach((button) => {
   button.addEventListener("click", () => {
     const productName = button.getAttribute("aria-label")?.replace("Add to cart: ", "") || "Item";

     button.textContent = "Added";
     button.setAttribute("aria-label", `Added to cart: ${productName}`);
     window.setTimeout(() => {
       button.textContent = "Add";
       button.setAttribute("aria-label", `Add to cart: ${productName}`);
     }, 1800);
   });
 });

 if (newsletterForm && emailInput && formStatus) {
   newsletterForm.addEventListener("submit", (event) => {
     event.preventDefault();

     formStatus.className = "form-status";

     if (!emailInput.validity.valid) {
       emailInput.setAttribute("aria-invalid", "true");
       formStatus.textContent = "Enter a valid email address to sign up.";
       formStatus.classList.add("error");
       emailInput.focus();
       return;
     }

     emailInput.removeAttribute("aria-invalid");
     formStatus.textContent = "Thanks. You are signed up for Northline Goods updates.";
     formStatus.classList.add("success");
     newsletterForm.reset();
   });
 }
   </script>
